import javax.annotation.Nonnull;
import java.util.Optional;
import java.util.function.Predicate;

public class CuriosCompat {

	public static void registerCuriosCapabilities(RegisterCapabilitiesEvent event) {
		event.registerItem(CuriosCapability.ITEM, (stack, context) -> new ICurio() {
				@Override
				public ItemStack getStack() {
					return stack;
				}

				@Nonnull
				@Override
				public SoundInfo getEquipSound(SlotContext slotContext) {
					return new SoundInfo(SoundEvents.ARMOR_EQUIP_GENERIC.value(), 1.0F, 1.0F);
				}

				@Override
				public void onEquip(SlotContext context, ItemStack prevStack) {
					//check that we don't have a cicada already on our head before trying to start the sound
					if (!context.entity().getItemBySlot(EquipmentSlot.HEAD).is(TFBlocks.CICADA.get().asItem())) {
						if (stack.is(TFBlocks.CICADA.get().asItem()) && !context.entity().level().isClientSide()) {
							PacketDistributor.sendToPlayersTrackingEntityAndSelf(context.entity(), new CreateMovingCicadaSoundPacket(context.entity().getId()));
						}
					}
				}

				@Override
				public boolean canEquipFromUse(SlotContext slotContext) {
					return true;
				}
			},
			TFItems.CHARM_OF_KEEPING_1, TFItems.CHARM_OF_KEEPING_2, TFItems.CHARM_OF_KEEPING_3, TFItems.CHARM_OF_LIFE_1, TFItems.CHARM_OF_LIFE_2,
			TFItems.NAGA_TROPHY, TFItems.LICH_TROPHY, TFItems.MINOSHROOM_TROPHY, TFItems.HYDRA_TROPHY, TFItems.KNIGHT_PHANTOM_TROPHY,
			TFItems.UR_GHAST_TROPHY, TFItems.ALPHA_YETI_TROPHY, TFItems.SNOW_QUEEN_TROPHY, TFItems.QUEST_RAM_TROPHY,
			TFBlocks.CICADA, TFBlocks.FIREFLY, TFBlocks.MOONWORM, TFItems.SKELETON_SKULL_CANDLE, TFItems.WITHER_SKELETON_SKULL_CANDLE,
			TFItems.ZOMBIE_SKULL_CANDLE, TFItems.CREEPER_SKULL_CANDLE, TFItems.PLAYER_SKULL_CANDLE, TFItems.PIGLIN_SKULL_CANDLE
		);
	}

	//if we have any curios and die with a charm of keeping on us, keep our curios instead of dropping them
	public static void keepCurios(DropRulesEvent event) {
		if (event.getEntity() instanceof Player player) {
			CompoundTag playerData = CharmEvents.getPlayerData(player);
			if (!player.level().isClientSide() && playerData.contains(CharmEvents.CONSUMED_CHARM_TAG) && player.hasData(TFDataAttachments.CHARM_INVENTORY) && !player.getData(TFDataAttachments.CHARM_INVENTORY).isEmpty()) {
				//Keep all Curios items
				CuriosApi.getCuriosInventory(player).ifPresent(modifiable -> {
					for (int i = 0; i < modifiable.getSlots(); ++i) {
						int finalI = i;
						//TODO: This is just what Curios does.
						@SuppressWarnings("removal")
						Predicate<ItemStack> isEquippedCurio = stack -> stack == modifiable.getEquippedCurios().getStackInSlot(finalI);
						event.addOverride(isEquippedCurio, DropRule.ALWAYS_KEEP);
					}
				});
			}
		}
	}

	public static void registerCurioLayers(EntityRenderersEvent.RegisterLayerDefinitions event) {
		event.registerLayerDefinition(TFModelLayers.CHARM_OF_LIFE, CharmOfLifeNecklaceModel::create);
	}

	public static void registerCurioRenderers(FMLClientSetupEvent event) {
		event.enqueueWork(() -> {
			ICurioRenderer.register(TFItems.CHARM_OF_LIFE_1.get(), () -> new CharmOfLifeNecklaceRenderer(ARGB.colorFromFloat(1.0F, 1.0F, 0.5F, 0.5F)));
			ICurioRenderer.register(TFItems.CHARM_OF_LIFE_2.get(), () -> new CharmOfLifeNecklaceRenderer(ARGB.colorFromFloat(1.0F, 1.0F, 0.9F, 0.0F)));
			ICurioRenderer.register(TFItems.CHARM_OF_KEEPING_1.get(), CharmOfKeepingRenderer::new);
			ICurioRenderer.register(TFItems.CHARM_OF_KEEPING_2.get(), CharmOfKeepingRenderer::new);
			ICurioRenderer.register(TFItems.CHARM_OF_KEEPING_3.get(), CharmOfKeepingRenderer::new);

			ICurioRenderer.register(TFItems.NAGA_TROPHY.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.LICH_TROPHY.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.MINOSHROOM_TROPHY.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.HYDRA_TROPHY.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.KNIGHT_PHANTOM_TROPHY.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.UR_GHAST_TROPHY.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.ALPHA_YETI_TROPHY.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.SNOW_QUEEN_TROPHY.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.QUEST_RAM_TROPHY.get(), CurioHeadRenderer::new);

			ICurioRenderer.register(TFBlocks.CICADA.get().asItem(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFBlocks.FIREFLY.get().asItem(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFBlocks.MOONWORM.get().asItem(), CurioHeadRenderer::new);

			ICurioRenderer.register(TFItems.CREEPER_SKULL_CANDLE.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.PIGLIN_SKULL_CANDLE.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.PLAYER_SKULL_CANDLE.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.SKELETON_SKULL_CANDLE.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.WITHER_SKELETON_SKULL_CANDLE.get(), CurioHeadRenderer::new);
			ICurioRenderer.register(TFItems.ZOMBIE_SKULL_CANDLE.get(), CurioHeadRenderer::new);
		});
	}

	public static void registerCustomRenderData(RegisterRenderStateModifiersEvent event) {
		event.registerEntityModifier(new TypeToken<LivingEntityRenderer<LivingEntity, LivingEntityRenderState, ?>>() {
		}, (LivingEntity living, LivingEntityRenderState state) -> {
			if (isCurioEquippedAndVisible(living, itemStack -> itemStack.getItem() instanceof BlockItem head && head.getBlock() instanceof AbstractTrophyBlock)) {
				state.setRenderData(RenderHooks.HIDE_HEAD_KEY, true);
			}
		});
	}
	public static boolean isCurioEquipped(LivingEntity entity, Predicate<ItemStack> stackPredicate) {
		return CuriosApi.getCuriosInventory(entity).flatMap(handler -> handler.findFirstCurio(stackPredicate)).isPresent();
	}

	public static boolean isCurioEquippedAndVisible(LivingEntity entity, Predicate<ItemStack> stackPredicate) {
		Optional<SlotResult> slot = CuriosApi.getCuriosInventory(entity).flatMap(handler -> handler.findFirstCurio(stackPredicate));
		return slot.isPresent() && slot.get().slotContext() != null && slot.get().slotContext().visible();
	}

	public static boolean findAndConsumeCurio(Item item, Player player, boolean saveItemToTag) {
		Optional<SlotResult> slot = CuriosApi.getCuriosInventory(player).flatMap(handler -> handler.findFirstCurio(item));
		return slot.isPresent() && TFItemStackUtils.consumeInventoryItem(
			slot.get().stack(),
			item,
			CharmEvents.getPlayerData(player),
			saveItemToTag,
			player.registryAccess()
		);
	}
}

package twilightforest.components.entity;

import com.mojang.serialization.Codec;
import com.mojang.serialization.MapCodec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.world.ItemStackWithSlot;
import net.minecraft.world.entity.EntityEquipment;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;

import java.util.ArrayList;
import java.util.List;

public record CharmAttachment(List<ItemStackWithSlot> items) {
	public static final MapCodec<CharmAttachment> CODEC = RecordCodecBuilder.mapCodec(i -> i.group(
		Codec.list(ItemStackWithSlot.CODEC)
			.fieldOf("items")
			.forGetter(CharmAttachment::items)
	).apply(i, CharmAttachment::new));

	public CharmAttachment {
		items = List.copyOf(items);
	}

	public CharmAttachment() {
		this(List.of());
	}

	public static CharmAttachment fromInventory(Inventory inventory) {
		List<ItemStackWithSlot> items = new ArrayList<>();

		for (int slot = 0; slot < inventory.getContainerSize(); slot++) {
			ItemStack stack = inventory.getItem(slot);

			if (!stack.isEmpty()) {
				items.add(new ItemStackWithSlot(slot, stack.copy()));
			}
		}

		return new CharmAttachment(items);
	}

	public Inventory toInventory(Player player) {
		Inventory inventory = new Inventory(player, new EntityEquipment());
		this.applyTo(inventory);
		return inventory;
	}

	public void applyTo(Inventory inventory) {
		for (ItemStackWithSlot item : items) {
			if (inventory.getItem(item.slot()).isEmpty()) {
				inventory.setItem(item.slot(), item.stack().copy());
			} else {
				inventory.add(item.stack().copy());
			}
		}
	}

	public boolean isEmpty() {
		return items.isEmpty();
	}
}

