// [VanillaCopy] super everything, but with appropriate redirections to our own datastructures. finer details noted
public class MagicMapItem extends MapItem {

	public static final String STR_ID = "magicmap";

	public MagicMapItem(Properties properties) {
		super(properties);
	}

	public static ItemStack setupNewMap(ServerLevel level, int worldX, int worldZ, byte scale, boolean trackingPosition, boolean unlimitedTracking) {
		ItemStack itemstack = new ItemStack(TFItems.FILLED_MAGIC_MAP.get());
		createMapData(itemstack, level, worldX, worldZ, scale, trackingPosition, unlimitedTracking, level.dimension());
		return itemstack;
	}

	@Nullable
	public static TFMagicMapData getData(ItemStack stack, Level level) {
		MapId mapid = stack.get(DataComponents.MAP_ID);

		if (mapid == null) {
			return null;
		}

		if (level instanceof ServerLevel serverLevel) {
			return MapDataManager.getServerMagicMapData(serverLevel, mapid);
		}

		return MapDataManager.getClientMagicMapData(mapid);
	}

	@Nullable
	public static TFMagicMapData getData(ItemStack stack, TooltipContext context) {
		MapId mapid = stack.get(DataComponents.MAP_ID);
		return mapid != null && context.mapData(mapid) instanceof TFMagicMapData mapData ? mapData : null;
	}

	@Nullable
	@Override
	protected TFMagicMapData getCustomMapData(ItemStack stack, Level level) {
		TFMagicMapData mapdata = getData(stack, level);
		if (mapdata == null && level instanceof ServerLevel serverLevel) {
			BlockPos sharedSpawnPos = level.getRespawnData().pos();
			mapdata = MagicMapItem.createMapData(stack, serverLevel, sharedSpawnPos.getX(), sharedSpawnPos.getZ(), 3, false, false, level.dimension());
		}

		return mapdata;
	}

	public static ColumnPos getMagicMapCenter(int x, int z) {
		// magic maps are aligned to the key biome grid so that 0,0 -> 2048,2048 is the covered area
		int mapSize = 2048;
		int roundX = (int) Math.round((double) (x - 1024) / mapSize);
		int roundZ = (int) Math.round((double) (z - 1024) / mapSize);
		int scaledX = roundX * mapSize + 1024;
		int scaledZ = roundZ * mapSize + 1024;
		return new ColumnPos(scaledX, scaledZ);
	}

	private static TFMagicMapData createMapData(ItemStack stack, ServerLevel level, int x, int z, int scale, boolean trackingPosition, boolean unlimitedTracking, ResourceKey<Level> dimension) {
		MapId freeMapId = level.getFreeMapId();
		ColumnPos pos = getMagicMapCenter(x, z);

		TFMagicMapData mapdata = new TFMagicMapData(pos.x(), pos.z(), (byte) scale, trackingPosition, unlimitedTracking, false, dimension);
		MapDataManager.saveServerMagicMapData(level, freeMapId, mapdata); // call our own save method
		stack.set(DataComponents.MAP_ID, freeMapId);
		stack.set(DataComponents.TOOLTIP_DISPLAY, stack.getOrDefault(DataComponents.TOOLTIP_DISPLAY, TooltipDisplay.DEFAULT).withHidden(DataComponents.MAP_ID, true));
		return mapdata;
	}

	public static String getMapName(int id) {
		return STR_ID + "_" + id;
	}

	private static final Map<ChunkPos, Holder<Biome>[]> CACHE = new HashMap<>();

	@Override
	public void update(Level level, Entity viewer, MapItemSavedData data) {
		if (level.dimension() == data.dimension && viewer instanceof Player && !level.isClientSide()) {
			int biomesPerPixel = 4;
			int blocksPerPixel = 16; // don't even bother with the scale, just hardcode it
			int centerX = data.centerX;
			int centerZ = data.centerZ;
			int viewerX = Mth.floor(viewer.getX() - centerX) / blocksPerPixel + 64;
			int viewerZ = Mth.floor(viewer.getZ() - centerZ) / blocksPerPixel + 64;
			int viewRadiusPixels = 512 / blocksPerPixel;

			int startX = (centerX / blocksPerPixel - 64) * biomesPerPixel;
			int startZ = (centerZ / blocksPerPixel - 64) * biomesPerPixel;
			Holder<Biome>[] biomes = CACHE.computeIfAbsent(new ChunkPos(startX, startZ), pos -> {
				@SuppressWarnings({"unchecked", "rawtypes"})
				Holder<Biome>[] array = new Holder[128 * biomesPerPixel * 128 * biomesPerPixel];
				for (int l = 0; l < 128 * biomesPerPixel; ++l) {
					for (int i1 = 0; i1 < 128 * biomesPerPixel; ++i1) {
						array[l * 128 * biomesPerPixel + i1] = level.getBiome(new BlockPos(startX * biomesPerPixel + i1 * biomesPerPixel, 0, startZ * biomesPerPixel + l * biomesPerPixel));
					}
				}
				return array;
			});

			Registry<Structure> structureRegistry = level.registryAccess().lookupOrThrow(Registries.STRUCTURE);

			for (int xPixel = viewerX - viewRadiusPixels + 1; xPixel < viewerX + viewRadiusPixels; ++xPixel) {
				for (int zPixel = viewerZ - viewRadiusPixels - 1; zPixel < viewerZ + viewRadiusPixels; ++zPixel) {
					if (xPixel >= 0 && zPixel >= 0 && xPixel < 128 && zPixel < 128) {
						int xPixelDist = xPixel - viewerX;
						int zPixelDist = zPixel - viewerZ;
						boolean shouldFuzz = xPixelDist * xPixelDist + zPixelDist * zPixelDist > (viewRadiusPixels - 2) * (viewRadiusPixels - 2);

						Holder<Biome> biome = biomes[xPixel * biomesPerPixel + zPixel * biomesPerPixel * 128 * biomesPerPixel];

						// make streams more visible
						Holder<Biome> overBiome = biomes[xPixel * biomesPerPixel + zPixel * biomesPerPixel * 128 * biomesPerPixel + 1];
						Holder<Biome> downBiome = biomes[xPixel * biomesPerPixel + (zPixel * biomesPerPixel + 1) * 128 * biomesPerPixel];
						biome = overBiome != null && overBiome.is(TFBiomes.STREAM) ? overBiome : downBiome != null && downBiome.is(TFBiomes.STREAM) ? downBiome : biome;

						MagicMapBiomeColor colorBrightness = this.getMapColorPerBiome(biome);

						MapColor mapcolor = colorBrightness.color();
						int brightness = colorBrightness.brightness();

						if (xPixelDist * xPixelDist + zPixelDist * zPixelDist < viewRadiusPixels * viewRadiusPixels && (!shouldFuzz || (xPixel + zPixel & 1) != 0)) {
							byte orgPixel = data.colors[xPixel + zPixel * 128];
							byte ourPixel = (byte) (mapcolor.id * 4 + brightness);

							if (orgPixel != ourPixel) {
								data.setColor(xPixel, zPixel, ourPixel);
								data.setDirty();
							}

							// look for TF features
							int worldX = (centerX / blocksPerPixel + xPixel - 64) * blocksPerPixel;
							int worldZ = (centerZ / blocksPerPixel + zPixel - 64) * blocksPerPixel;
							if (LegacyLandmarkPlacements.blockIsInLandmarkCenter(worldX, worldZ)) {
								ResourceKey<Structure> structureKey = LegacyLandmarkPlacements.pickLandmarkAtBlock(worldX, worldZ, level);
								// Filters by structures we want to give icons for
								if (structureRegistry.get(structureKey).map(structureRef -> structureRef.is(TFStructureTags.LANDMARK)).orElse(false)) {
									TFMagicMapData tfData = (TFMagicMapData) data;
									if (structureRegistry.getOrThrow(structureKey).value() instanceof LandmarkStructure landmark) {
										landmark.getMapIcon().ifPresent(icon -> tfData.addTFDecoration(icon, level, makeName(icon, worldX, worldZ), worldX, worldZ, 180.0F, LandmarkUtil.isConquered(level, worldX, worldZ)));
										//TwilightForestMod.LOGGER.info("Found feature at {}, {}. Placing it on the map at {}, {}", worldX, worldZ, mapX, mapZ);
									}
								}
							}
						}
					}
				}
			}
		}
	}

	public static String makeName(Holder<MapDecorationType> type, int x, int z) {
		return type.value().assetId() + "_" + x + "_" + z;
	}

	private MagicMapBiomeColor getMapColorPerBiome(Holder<Biome> biome) {
		MagicMapBiomeColor color = biome.getData(TFDataMaps.MAGIC_MAP_BIOME_COLOR);
		return color != null ? color : new MagicMapBiomeColor(MapColor.COLOR_MAGENTA);
	}

	@Override
	public void appendHoverText(ItemStack stack, TooltipContext context, TooltipDisplay display, Consumer<Component> builder, TooltipFlag flag) {
		MapId mapId = stack.get(DataComponents.MAP_ID);
		if (mapId != null) {
			if (flag.isAdvanced()) {
				MapItemSavedData mapitemsaveddata = MapDataManager.getClientMagicMapData(mapId);
				if (mapitemsaveddata != null) {
					builder.accept(Component.translatable("filled_map.id", mapId.id()).withStyle(ChatFormatting.GRAY));
					builder.accept(Component.translatable("filled_map.scale", 1 << mapitemsaveddata.scale).withStyle(ChatFormatting.GRAY));
					builder.accept(Component.translatable("filled_map.level", mapitemsaveddata.scale, 4).withStyle(ChatFormatting.GRAY));
				} else {
					builder.accept(Component.translatable("filled_map.unknown").withStyle(ChatFormatting.GRAY));
				}
			} else builder.accept(Component.translatable("filled_map.id", mapId.id()).withStyle(ChatFormatting.GRAY));
		}
	}
}

package twilightforest.item.mapdata;

import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.saveddata.maps.MapId;
import net.neoforged.neoforge.client.event.ClientPlayerNetworkEvent;
import org.jspecify.annotations.Nullable;

import java.util.HashMap;
import java.util.Map;

/*
* Most of the content in this class is adapted from implementations in ServerLevel and ClientLevel.
*/
public final class MapDataManager {
	private static final Map<MapId, TFMagicMapData> MAGIC_MAP_CLIENT_DATA = new HashMap<>();
	private static final Map<MapId, TFMazeMapData> MAZE_MAP_CLIENT_DATA = new HashMap<>();

	public static @Nullable TFMagicMapData getServerMagicMapData(ServerLevel serverLevel, MapId id) {
		return serverLevel.getServer().getDataStorage().get(TFMagicMapData.magicMapType(id));
	}

	public static @Nullable TFMazeMapData getServerMazeMapData(ServerLevel serverLevel, MapId id) {
		return serverLevel.getServer().getDataStorage().get(TFMazeMapData.mazeMapType(id));
	}

	public static @Nullable TFMagicMapData getClientMagicMapData(MapId id) {
		return MAGIC_MAP_CLIENT_DATA.get(id);
	}

	public static @Nullable TFMazeMapData getClientMazeMapData(MapId id) {
		return MAZE_MAP_CLIENT_DATA.get(id);
	}

	public static void saveServerMagicMapData(ServerLevel serverLevel, MapId id, TFMagicMapData data) {
		serverLevel.getServer().getDataStorage().set(TFMagicMapData.magicMapType(id), data);
	}

	public static void saveServerMazeMapData(ServerLevel serverLevel, MapId id, TFMazeMapData data) {
		serverLevel.getServer().getDataStorage().set(TFMazeMapData.mazeMapType(id), data);
	}

	public static void saveClientMagicMapData(MapId id, TFMagicMapData data) {
		MAGIC_MAP_CLIENT_DATA.put(id, data);
	}

	public static void saveClientMazeMapData(MapId id, TFMazeMapData data) {
		MAZE_MAP_CLIENT_DATA.put(id, data);
	}

	public static void clearCache(ClientPlayerNetworkEvent.LoggingOut event) {
		MAGIC_MAP_CLIENT_DATA.clear();
		MAZE_MAP_CLIENT_DATA.clear();
	}
}

package twilightforest.item.mapdata;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.Holder;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientboundMapItemDataPacket;
import net.minecraft.resources.ResourceKey;
import net.minecraft.util.Mth;
import net.minecraft.util.datafix.DataFixTypes;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.saveddata.SavedDataType;
import net.minecraft.world.level.saveddata.maps.*;
import org.jspecify.annotations.Nullable;
import twilightforest.TwilightForestMod;
import twilightforest.item.MagicMapItem;
import twilightforest.network.MagicMapPacket;
import twilightforest.util.Codecs;

import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;

public class TFMagicMapData extends MapItemSavedData {
	public final List<String> conqueredStructures = new ArrayList<>();

	// [VanillaCopy] from MapItemSavedData but with our own fields and constructor
	public static final Codec<TFMagicMapData> CODEC = RecordCodecBuilder.create(i ->
		i.group(
			Level.RESOURCE_KEY_CODEC
				.fieldOf("dimension")
				.forGetter(m -> m.dimension),
			Codec.INT
				.fieldOf("xCenter")
				.forGetter(m -> m.centerX),
			Codec.INT
				.fieldOf("zCenter")
				.forGetter(m -> m.centerZ),
			Codec.BYTE
				.optionalFieldOf("scale", (byte) 0)
				.forGetter(m -> m.scale),
			Codec.BYTE_BUFFER
				.fieldOf("colors")
				.forGetter(m -> ByteBuffer.wrap(m.colors)),
			Codec.BOOL
				.optionalFieldOf("trackingPosition", true)
				.forGetter(m -> m.trackingPosition),
			Codec.BOOL
				.optionalFieldOf("unlimitedTracking", false)
				.forGetter(m -> m.unlimitedTracking),
			Codec.BOOL
				.optionalFieldOf("locked", false)
				.forGetter(m -> m.locked),
			MapBanner.CODEC
				.listOf()
				.optionalFieldOf("banners", List.of())
				.forGetter(m -> List.copyOf(m.bannerMarkers.values())),
			MapFrame.CODEC
				.listOf()
				.optionalFieldOf("frames", List.of())
				.forGetter(m -> List.copyOf(m.frameMarkers.values())),
			DecorationHolder.CODEC
				.listOf()
				.optionalFieldOf("decorations", List.of())
				.forGetter(m -> {
					List<DecorationHolder> holders = new ArrayList<>();
					m.decorations.forEach((id, decoration) -> {
						if (decoration.type().value().showOnItemFrame()) {
							holders.add(new DecorationHolder(id, decoration));
						}
					});
					return holders;
				}),
			Codec.STRING
				.listOf()
				.optionalFieldOf("conquered_structures", List.of())
				.forGetter(m -> List.copyOf(m.conqueredStructures))
		).apply(i, TFMagicMapData::new)
	);

	// [VanillaCopy] from MapItemSavedData but changed to use our Codec and namespace
	public static SavedDataType<TFMagicMapData> magicMapType(MapId id) {
		return new SavedDataType<>(TwilightForestMod.prefix(id.key()), () -> {
			throw new IllegalStateException("Should never create an empty map saved data");
		}, CODEC, DataFixTypes.SAVED_DATA_MAP_DATA);
	}

	// [VanillaCopy] from MapItemSavedData
	public TFMagicMapData(int centerX, int centerZ, byte scale, boolean trackingPosition, boolean unlimitedTracking, boolean locked, ResourceKey<Level> dimension) {
		super(centerX, centerZ, scale, trackingPosition, unlimitedTracking, locked, dimension);
	}

	// [VanillaCopy] from MapItemSavedData but with our own fields
	private TFMagicMapData(ResourceKey<Level> dimension, int centerX, int centerZ, byte scale, ByteBuffer colors, boolean trackingPosition, boolean unlimitedTracking, boolean locked, List<MapBanner> banners, List<MapFrame> frames, List<DecorationHolder> decorations, List<String> conqueredStructures) {
		this(centerX, centerZ, (byte) Mth.clamp(scale, 0, 4), trackingPosition, unlimitedTracking, locked, dimension);

		if (colors.array().length == 16384) {
			this.colors = colors.array();
		}

		for(MapBanner banner : banners) {
			this.bannerMarkers.put(banner.getId(), banner);
			this.addDecoration(banner.getDecoration(), null, banner.getId(), banner.pos().getX(), banner.pos().getZ(), 180.0F, banner.name().orElse(null));
		}

		for(MapFrame frame : frames) {
			this.frameMarkers.put(frame.getId(), frame);
			this.addDecoration(MapDecorationTypes.FRAME, null, getFrameKey(frame.entityId()), frame.pos().getX(), frame.pos().getZ(), frame.rotation(), null);
		}

		for (DecorationHolder holder : decorations) {
			MapDecoration newDecoration = holder.decoration();
			MapDecoration oldDecoration = this.decorations.put(holder.id(), newDecoration);

			if (!newDecoration.equals(oldDecoration)) {
				if (oldDecoration != null && oldDecoration.type().value().trackCount()) {
					this.trackedDecorationCount--;
				}

				if (newDecoration.type().value().trackCount()) {
					this.trackedDecorationCount++;
				}
			}
		}

		this.conqueredStructures.addAll(conqueredStructures);
	}

	@Nullable
	@Override
	public Packet<?> getUpdatePacket(MapId mapId, Player player) {
		Packet<?> packet = super.getUpdatePacket(mapId, player);
		return packet instanceof ClientboundMapItemDataPacket mapItemDataPacket ? new MagicMapPacket(mapItemDataPacket, this.conqueredStructures).toVanillaClientbound() : packet;
	}

	public void addTFDecoration(Holder<MapDecorationType> decorationType, @Nullable LevelAccessor level, String id, double x, double z, double yRot, boolean conquered) {
		this.addDecoration(decorationType, level, id, x, z, yRot, null);
		MapDecoration deco = this.decorations.get(id);
		if (deco != null) {
			String conqueredID = MagicMapItem.makeName(decorationType, deco.x(), deco.y());
			if (conquered && !this.conqueredStructures.contains(conqueredID)) {
				this.conqueredStructures.add(conqueredID);
			} else if (!conquered) {
				this.conqueredStructures.remove(conqueredID);
			}
		}
	}

	public record DecorationHolder(String id, MapDecoration decoration) {
		public static final Codec<DecorationHolder> CODEC = RecordCodecBuilder.create(instance -> instance.group(
			Codec.STRING.fieldOf("id").forGetter(DecorationHolder::id),
			Codecs.DECORATION_CODEC.fieldOf("decoration").forGetter(DecorationHolder::decoration)
		).apply(instance, DecorationHolder::new));
	}
}

