		i.group(
			Level.RESOURCE_KEY_CODEC
				.fieldOf("dimension")
				.forGetter(m -> m.dimension),
			Codec.INT
				.fieldOf("xCenter")
				.forGetter(m -> m.centerX),
			Codec.INT
				.fieldOf("zCenter")
				.forGetter(m -> m.centerZ),
			Codec.BYTE
				.optionalFieldOf("scale", (byte) 0)
				.forGetter(m -> m.scale),
			Codec.BYTE_BUFFER
				.fieldOf("colors")
				.forGetter(m -> ByteBuffer.wrap(m.colors)),
